-- =====================================================================
-- 014 · Unidad 17 completa (Libro 2): 6 temas nuevos
--   ep8-ing-adjetivos, ep8-ing-ed, ep8-pasado-progresivo,
--   ep8-futuro-progresivo, ep8-actividades, ep8-joyeria-telas
--   - pensum (Nivel 8, orden 10 a 15), lecciones en la Unidad 17 (orden 8 a 13)
--   - 48 ejercicios de lección, 48 de banco, 18 reservados para examen
-- Requiere 001 a 013. Se puede correr varias veces sin dañar nada.
-- =====================================================================

-- ============ TEMAS ============
on conflict (id) do update set episodio = excluded.episodio, orden = excluded.orden,
  nombre_es = excluded.nombre_es, nombre_en = excluded.nombre_en, descripcion = excluded.descripcion;

-- ============ LECCIONES (Unidad 17) ============
on conflict (id) do update set unidad_id = excluded.unidad_id, episodio = excluded.episodio, orden = excluded.orden,
  tipo = excluded.tipo, titulo = excluded.titulo, descripcion = excluded.descripcion;

-- ============ EJERCICIOS ============
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo,
  datos = excluded.datos, tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;

-- Listo: 6 temas de la Unidad 17 con 114 filas de ejercicios.
